export const BASIC_CAMERAS=[
['person-front','person','Ngang mắt','Tự nhiên, giữ khuôn mặt rõ.','Hold the camera at the visible eye level and preserve the source framing. Gentle natural breathing only; no reframing to a hidden face.','still'],
['person-close','person','Cận mặt','Tiến nhẹ, nhấn biểu cảm.','Slow restrained camera push toward the visible face, no more than 8 percent tighter. Keep full head and facial geometry intact.','push'],
['person-three','person','Góc 3/4','Lệch nhẹ, tạo chiều sâu.','A tiny camera arc of at most 8 degrees toward a three-quarter portrait; preserve identity and stop before unseen face details are exposed.','orbit'],
['person-low','person','Góc thấp','Hạ nhẹ máy, dáng nổi bật.','Lower the camera only slightly while tilting gently upward; keep natural body proportions and the visible source pose, no extreme low angle.','low'],
['person-high','person','Góc cao','Nhìn xuống nhẹ, mềm mại.','Raise the camera slightly and tilt down gently, preserving the current pose and visible anatomy. Do not invent the top of the head or unseen limbs.','high'],
['person-follow','person','Theo nhân vật','Máy theo chuyển động nhỏ.','Track laterally a short distance with the subject, preserving original screen position and distance. If walking is not supported by the image use a subtle lateral camera drift only.','slide'],
['product-front','product','Chính diện','Giữ hình dáng và nhãn rõ.','Locked frontal product hero from the existing source viewpoint. Product stays rigid and grounded, original label and cap remain unchanged.','still'],
['product-push','product','Tiến vào','Nhấn nhãn hoặc chất liệu.','Slow camera push in no more than 10 percent toward the product front label. Product remains physically stationary; preserve printing, cap and rigid geometry.','push'],
['product-orbit','product','Vòng nhẹ','Lượn tối đa 10°, thêm chiều sâu.','Camera arcs at most 10 degrees around the stationary product, with restrained parallax. Do not rotate the bottle or expose unsupported rear packaging.','orbit'],
['product-overhead','product','Từ trên xuống','Nâng nhẹ máy, nhìn bố cục.','Tilt downward from a slightly elevated camera, a small change from the actual source angle only. Avoid inventing a hidden top surface or a complete overhead view from a frontal image.','high'],
['product-low','product','Góc thấp','Tôn dáng sản phẩm.','Low hero camera with only a small downward camera shift and gentle upward tilt. Keep true packaging proportions and a stable contact shadow, no towering deformation.','low'],
['product-slide','product','Trượt ngang','Lướt qua, sản phẩm đứng yên.','Slow short lateral camera slide, at most 8 percent of the frame width. Keep product stationary, label readable, reflections consistent and no product duplication.','slide']
];
export function basicCameraDirection(id){return BASIC_CAMERAS.find(p=>p[0]===id)?.[4]||''}
export function createVideoCameraPicker(React){const{createElement:h,useState:S}=React;return function CameraPicker({value,onChange,disabled=false}){const[group,G]=S('person');const current=BASIC_CAMERAS.find(x=>x[0]===value);return h('section',{className:'basic-camera-picker'},h('header',null,h('strong',null,'Góc camera'),value&&h('button',{type:'button',disabled,title:'Bỏ góc camera đã chọn','aria-label':'Bỏ góc camera đã chọn',onClick:()=>onChange('')},'×')),h('div',{className:'basic-camera-groups',role:'group','aria-label':'Chủ thể camera'},...[["person","Người"],["product","Sản phẩm"]].map(([id,label])=>h('button',{type:'button',disabled,'aria-pressed':group===id,onClick:()=>G(id)},label))),h('div',{className:'basic-camera-grid'},...BASIC_CAMERAS.filter(p=>p[1]===group).map(([id,_,label,note,direction,motion])=>h('button',{type:'button',key:id,disabled,'aria-pressed':value===id,title:label+' · '+note,onClick:()=>onChange(value===id?'':id)},h('svg',{viewBox:'0 0 64 42',width:64,height:42,fill:'none',stroke:'currentColor',strokeWidth:1.5,'aria-hidden':true,className:'camera-diagram camera-'+motion},group==='person'?h('g',null,h('circle',{cx:38,cy:13,r:5}),h('path',{d:'M29 32v-5a9 9 0 0 1 18 0v5'})):h('g',null,h('rect',{x:33,y:14,width:12,height:21,rx:3}),h('path',{d:'M36 14V8h6v6M35 24h8'})),h('g',{className:'camera-mini'},h('rect',{x:9,y:20,width:11,height:8,rx:2}),h('path',{d:'M20 22l5-3v10l-5-3'})),h('path',{className:'camera-path',d:motion==='high'?'M13 16Q15 5 29 7':motion==='low'?'M14 32Q19 39 29 34':motion==='orbit'?'M22 8Q59 0 53 31':motion==='slide'?'M6 35h20':motion==='push'?'M23 24h7':'M24 24h4',strokeDasharray:'2 3'})),h('span',null,label),h('small',null,note)))),h('p',{className:'camera-selection-note',role:'status'},current?current[2]+' · '+current[3]:'Tùy chọn · không chọn thì giữ camera theo prompt.'))}}
